133→// formatSettingsStatusShort formats a short settings status line.
134→// Output format: "● Enabled · manual-commit · branch main" or "○ Disabled · auto-commit"
135→func formatSettingsStatusShort(ctx context.Context, s *EntireSettings, sty statusStyles) string {
136→	displayName := s.Strategy
137→	if dn, ok := strategyInternalToDisplay[s.Strategy]; ok {
138→		displayName = dn
139→	}
140→
141→	var b strings.Builder
142→
143→	if s.Enabled {
144→		b.WriteString(sty.render(sty.green, "●"))
145→		b.WriteString(" ")
146→		b.WriteString(sty.render(sty.bold, "Enabled"))
147→	} else {
148→		b.WriteString(sty.render(sty.red, "○"))
149→		b.WriteString(" ")
150→		b.WriteString(sty.render(sty.bold, "Disabled"))
151→	}
152→
153→	b.WriteString(sty.render(sty.dim, " · "))
154→	b.WriteString(displayName)
155→
156→	// Resolve branch from repo root
157→	if repoRoot, err := paths.RepoRoot(ctx); err == nil {
158→		if branch := resolveWorktreeBranch(ctx, repoRoot); branch != "" {
159→			b.WriteString(sty.render(sty.dim, " · "))
160→			b.WriteString("branch ")
161→			b.WriteString(sty.render(sty.cyan, branch))
162→		}
163→	}
164→
165→	return b.String()
166→}
