192→// timeAgo formats a time as a human-readable relative duration.
193→func timeAgo(t time.Time) string {
194→	d := time.Since(t)
195→	switch {
196→	case d < time.Minute:
197→		return "just now"
198→	case d < time.Hour:
199→		m := int(d.Minutes())
200→		return fmt.Sprintf("%dm ago", m)
201→	case d < 24*time.Hour:
202→		h := int(d.Hours())
203→		return fmt.Sprintf("%dh ago", h)
204→	default:
205→		days := int(d.Hours() / 24)
206→		return fmt.Sprintf("%dd ago", days)
207→	}
208→}
