210→// worktreeGroup groups sessions by worktree path for display.
211→type worktreeGroup struct {
212→	path     string
213→	branch   string
214→	sessions []*session.State
215→}
216→
217→const (
218→	unknownPlaceholder  = "(unknown)"
219→	detachedHEADDisplay = "HEAD"
220→)
221→
222→// writeActiveSessions writes active session information grouped by worktree.
223→func writeActiveSessions(ctx context.Context, w io.Writer, sty statusStyles) {
224→	store, err := session.NewStateStore(ctx)
225→	if err != nil {
226→		return
227→	}
228→
229→	states, err := store.List(ctx)
230→	if err != nil || len(states) == 0 {
231→		return
232→	}
233→
234→	// Filter to active sessions only
235→	var active []*session.State
236→	for _, s := range states {
237→		if s.EndedAt == nil {
238→			active = append(active, s)
239→		}
240→	}
241→	if len(active) == 0 {
242→		return
243→	}
244→
245→	// Group by worktree path
246→	groups := make(map[string]*worktreeGroup)
247→	for _, s := range active {
248→		wp := s.WorktreePath
249→		if wp == "" {
250→			wp = unknownPlaceholder
251→		}
252→		g, ok := groups[wp]
253→		if !ok {
254→			g = &worktreeGroup{path: wp}
255→			groups[wp] = g
256→		}
257→		g.sessions = append(g.sessions, s)
258→	}
259→
260→	// Resolve branch names for each worktree (skip for unknown paths)
261→	for _, g := range groups {
262→		if g.path != unknownPlaceholder {
263→			g.branch = resolveWorktreeBranch(ctx, g.path)
264→		}
265→	}
266→
267→	// Sort groups: alphabetical by path
268→	sortedGroups := make([]*worktreeGroup, 0, len(groups))
269→	for _, g := range groups {
270→		sortedGroups = append(sortedGroups, g)
271→	}
272→	sort.Slice(sortedGroups, func(i, j int) bool {
273→		return sortedGroups[i].path < sortedGroups[j].path
274→	})
275→
276→	// Sort sessions within each group by StartedAt (newest first)
277→	for _, g := range sortedGroups {
278→		sort.Slice(g.sessions, func(i, j int) bool {
279→			return g.sessions[i].StartedAt.After(g.sessions[j].StartedAt)
280→		})
281→	}
282→
283→	// Track aggregate totals
284→	var totalSessions int
285→
286→	fmt.Fprintln(w)
287→	printedHeader := false
288→	for _, g := range sortedGroups {
289→		if !printedHeader {
290→			fmt.Fprintln(w, sty.sectionRule("Active Sessions", sty.width))
291→			fmt.Fprintln(w)
292→			printedHeader = true
293→		}
294→
295→		for _, st := range g.sessions {
296→			totalSessions++
297→
298→			agentLabel := string(st.AgentType)
299→			if agentLabel == "" {
300→				agentLabel = unknownPlaceholder
301→			}
302→
303→			shortID := st.SessionID
304→			if len(shortID) > 7 {
305→				shortID = shortID[:7]
306→			}
307→
308→			// Line 1: Agent · shortID
309→			fmt.Fprintf(w, "%s %s %s\n",
310→				sty.render(sty.agent, agentLabel),
311→				sty.render(sty.dim, "·"),
312→				shortID)
313→
314→			// Line 2: > "first prompt" (chevron + quoted, truncated)
315→			if st.FirstPrompt != "" {
316→				prompt := stringutil.TruncateRunes(st.FirstPrompt, 60, "...")
317→				fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
318→			}
319→
320→			// Line 3: stats line — started Xd ago · active now · files N · tokens X.Xk
321→			var stats []string
322→			stats = append(stats, "started "+timeAgo(st.StartedAt))
323→
324→			if st.LastInteractionTime != nil && st.LastInteractionTime.Sub(st.StartedAt) > time.Minute {
325→				stats = append(stats, activeTimeDisplay(st.LastInteractionTime))
326→			}
327→
328→			stats = append(stats, "tokens "+formatTokenCount(totalTokens(st.TokenUsage)))
329→
330→			statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
331→			fmt.Fprintln(w, sty.render(sty.dim, statsLine))
332→			fmt.Fprintln(w)
333→		}
334→	}
335→
336→	// Footer: horizontal rule + session count
337→	fmt.Fprintln(w, sty.horizontalRule(sty.width))
338→	var footer string
339→	if totalSessions == 1 {
340→		footer = "1 session"
341→	} else {
342→		footer = fmt.Sprintf("%d sessions", totalSessions)
343→	}
344→	fmt.Fprintln(w, sty.render(sty.dim, footer))
345→	fmt.Fprintln(w)
346→}
