348→// resolveWorktreeBranch resolves the current branch for a worktree path
349→// by reading the HEAD ref directly from the filesystem
350→func resolveWorktreeBranch(ctx context.Context, worktreePath string) string {
351→	gitPath := filepath.Join(worktreePath, ".git")
352→
353→	fi, err := os.Stat(gitPath)
354→	if err != nil {
355→		return ""
356→	}
357→
358→	var headPath string
359→	if fi.IsDir() {
360→		// Regular repo: .git is a directory
361→		headPath = filepath.Join(gitPath, "HEAD")
362→	} else {
363→		// Worktree: .git is a file containing "gitdir: <path>"
364→		data, err := os.ReadFile(gitPath) //nolint:gosec // path derived from known worktree dir
365→		if err != nil {
366→			return ""
367→		}
368→		content := strings.TrimSpace(string(data))
369→		if !strings.HasPrefix(content, "gitdir: ") {
370→			return ""
371→		}
372→		gitdirPath := strings.TrimPrefix(content, "gitdir: ")
373→		if !filepath.IsAbs(gitdirPath) {
374→			gitdirPath = filepath.Join(worktreePath, gitdirPath)
375→		}
376→		headPath = filepath.Join(gitdirPath, "HEAD")
377→	}
378→
379→	data, err := os.ReadFile(headPath) //nolint:gosec // path constructed from .git/HEAD
380→	if err != nil {
381→		return ""
382→	}
383→
384→	ref := strings.TrimSpace(string(data))
385→
386→	// Symbolic ref: "ref: refs/heads/<branch>"
387→	if strings.HasPrefix(ref, "ref: refs/heads/") {
388→		branch := strings.TrimPrefix(ref, "ref: refs/heads/")
389→		// Reftable ref storage uses "ref: refs/heads/.invalid" as a dummy HEAD stub.
390→		// Fall back to git to resolve the actual branch in that case.
391→		if branch == ".invalid" {
392→			return resolveWorktreeBranchGit(ctx, worktreePath)
393→		}
394→		return branch
395→	}
396→
397→	// Detached HEAD or other ref type
398→	return detachedHEADDisplay
399→}
400→
401→// resolveWorktreeBranchGit resolves the branch name by shelling out to git.
402→// Used as a fallback for reftable ref storage where .git/HEAD is a stub.
403→func resolveWorktreeBranchGit(ctx context.Context, worktreePath string) string {
404→	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
405→	defer cancel()
406→	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--symbolic-full-name", "HEAD")
407→	out, err := cmd.Output()
408→	if err != nil {
409→		return detachedHEADDisplay
410→	}
411→	ref := strings.TrimSpace(string(out))
412→	if strings.HasPrefix(ref, "refs/heads/") {
413→		return strings.TrimPrefix(ref, "refs/heads/")
414→	}
415→	return detachedHEADDisplay
416→}
