 20→// stalenessThreshold is the duration after which an active session is considered stuck.
 21→const stalenessThreshold = 1 * time.Hour
 22→
 23→func newDoctorCmd() *cobra.Command {
 24→	var forceFlag bool
 25→
 26→	cmd := &cobra.Command{
 27→		Use:   "doctor",
 28→		Short: "Fix stuck sessions",
 29→		Long: `Scan for stuck or problematic sessions and offer to fix them.
 30→
 31→A session is considered stuck if:
 32→  - It is in ACTIVE phase with no interaction for over 1 hour
 33→  - It is in ENDED phase with uncondensed checkpoint data on a shadow branch
 34→
 35→For each stuck session, you can choose to:
 36→  - Condense: Save session data to permanent storage (entire/checkpoints/v1 branch)
 37→  - Discard: Remove the session state and shadow branch data
 38→  - Skip: Leave the session as-is
 39→
 40→Use --force to condense all fixable sessions without prompting.  Sessions that can't
 41→be condensed will be discarded.`,
 42→		RunE: func(cmd *cobra.Command, _ []string) error {
 43→			return runSessionsFix(cmd, forceFlag)
 44→		},
 45→	}
 46→
 47→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Fix all stuck sessions without prompting (condense if possible, otherwise discard)")
 48→
 49→	return cmd
 50→}
 51→
 52→// stuckSession holds a session state along with diagnostic info.
 53→type stuckSession struct {
 54→	State             *strategy.SessionState
 55→	Reason            string
 56→	ShadowBranch      string
 57→	HasShadowBranch   bool
 58→	CheckpointCount   int
 59→	FilesTouchedCount int
 60→}
 61→
 62→func runSessionsFix(cmd *cobra.Command, force bool) error {
 63→	ctx := cmd.Context()
 64→	// Load all session states
 65→	states, err := strategy.ListSessionStates(ctx)
 66→	if err != nil {
 67→		return fmt.Errorf("failed to list session states: %w", err)
 68→	}
 69→
 70→	if len(states) == 0 {
 71→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 72→		return nil
 73→	}
 74→
 75→	// Open repository to check shadow branches (uses worktree-aware helper)
 76→	repo, err := openRepository(ctx)
 77→	if err != nil {
 78→		return fmt.Errorf("failed to open repository: %w", err)
 79→	}
 80→
 81→	// Identify stuck sessions
 82→	now := time.Now()
 83→	var stuck []stuckSession
 84→
 85→	for _, state := range states {
 86→		ss := classifySession(state, repo, now)
 87→		if ss != nil {
 88→			stuck = append(stuck, *ss)
 89→		}
 90→	}
 91→
 92→	if len(stuck) == 0 {
 93→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 94→		return nil
 95→	}
 96→
 97→	// Get the current strategy for condense operations
 98→	strat := GetStrategy()
 99→	condenser, canCondense := strat.(strategy.SessionCondenser)
100→
101→	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
102→
103→	for _, ss := range stuck {
104→		displayStuckSession(cmd, ss)
105→
106→		if force {
107→			if canCondense && ss.HasShadowBranch && ss.CheckpointCount > 0 {
108→				if err := condenser.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
109→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
110→				} else {
111→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
112→				}
113→			} else {
114→				// Discard if we can't condense
115→				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
116→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
117→				} else {
118→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
119→				}
120→			}
121→			continue
122→		}
123→
124→		// Interactive: prompt for action
125→		action, err := promptSessionAction(ss, canCondense)
126→		if err != nil {
127→			if errors.Is(err, huh.ErrUserAborted) {
128→				return nil
129→			}
130→			return fmt.Errorf("failed to get action: %w", err)
131→		}
132→
133→		switch action {
134→		case "condense":
135→			if !canCondense {
136→				fmt.Fprintf(cmd.ErrOrStderr(), "Strategy %s does not support condensation\n", strat.Name())
137→				continue
138→			}
139→			if err := condenser.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
140→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
141→			} else {
142→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
143→			}
144→		case "discard":
145→			if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
146→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
147→			} else {
148→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
149→			}
150→		case "skip":
151→			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
152→		}
153→	}
154→
155→	return nil
156→}
157→
158→// classifySession determines if a session is stuck and returns diagnostic info.
159→// Returns nil if the session is healthy.
160→func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
161→	// Determine shadow branch info
162→	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
163→	refName := plumbing.NewBranchReferenceName(shadowBranch)
164→	_, refErr := repo.Reference(refName, true)
165→	hasShadowBranch := refErr == nil
166→
167→	switch {
168→	case state.Phase.IsActive():
169→		// Active sessions are stuck if no interaction for over the staleness threshold
170→		isStale := state.LastInteractionTime == nil || now.Sub(*state.LastInteractionTime) > stalenessThreshold
171→		if !isStale {
172→			return nil
173→		}
174→
175→		var reason string
176→		if state.LastInteractionTime != nil {
177→			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
178→		} else {
179→			reason = "active, no recorded interaction time"
180→		}
181→
182→		return &stuckSession{
183→			State:             state,
184→			Reason:            reason,
185→			ShadowBranch:      shadowBranch,
186→			HasShadowBranch:   hasShadowBranch,
187→			CheckpointCount:   state.StepCount,
188→			FilesTouchedCount: len(state.FilesTouched),
189→		}
190→
191→	case state.Phase == session.PhaseEnded:
192→		// Ended sessions are stuck if they have uncondensed data
193→		if state.StepCount <= 0 || !hasShadowBranch {
194→			return nil
195→		}
196→
197→		return &stuckSession{
198→			State:             state,
199→			Reason:            "ended with uncondensed checkpoint data",
200→			ShadowBranch:      shadowBranch,
201→			HasShadowBranch:   hasShadowBranch,
202→			CheckpointCount:   state.StepCount,
203→			FilesTouchedCount: len(state.FilesTouched),
204→		}
205→
206→	default:
207→		return nil
208→	}
209→}
210→
211→// displayStuckSession prints diagnostic info for a stuck session.
212→func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
213→	w := cmd.OutOrStdout()
214→
215→	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
216→	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
217→	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
218→
219→	if ss.State.AgentType != "" {
220→		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
221→	}
222→
223→	if ss.State.LastInteractionTime != nil {
224→		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
225→	}
226→
227→	shadowStatus := "not found"
228→	if ss.HasShadowBranch {
229→		shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
230→	}
231→	fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
232→	fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
233→}
234→
235→// promptSessionAction asks the user what to do with a stuck session.
236→func promptSessionAction(ss stuckSession, canCondense bool) (string, error) {
237→	var action string
238→
239→	options := make([]huh.Option[string], 0, 3)
240→	if canCondense && ss.HasShadowBranch && ss.CheckpointCount > 0 {
241→		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
242→	}
243→	options = append(options,
244→		huh.NewOption("Discard (remove session data)", "discard"),
245→		huh.NewOption("Skip (leave as-is)", "skip"),
246→	)
247→
248→	form := NewAccessibleForm(
249→		huh.NewGroup(
250→			huh.NewSelect[string]().
251→				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
252→				Options(options...).
253→				Value(&action),
254→		),
255→	)
256→
257→	if err := form.Run(); err != nil {
258→		return "", fmt.Errorf("session fix prompt failed: %w", err)
259→	}
260→
261→	return action, nil
262→}
263→
264→// discardSession removes session state and cleans up the shadow branch.
265→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
266→	// Clear session state file
267→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
268→		return fmt.Errorf("failed to clear session state: %w", err)
269→	}
270→
271→	// Delete shadow branch if it exists and no other sessions need it
272→	if ss.HasShadowBranch {
273→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
274→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
275→		} else if shouldDelete {
276→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
277→				// Branch already gone is not an error — keeps discard idempotent
278→				if !errors.Is(err, strategy.ErrBranchNotFound) {
279→					return fmt.Errorf("failed to delete shadow branch: %w", err)
280→				}
281→			}
282→		}
283→	}
284→
285→	return nil
286→}
287→
288→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
289→// Returns true if no other sessions (besides excludeSessionID) need this branch.
290→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
291→	states, err := strategy.ListSessionStates(ctx)
292→	if err != nil {
293→		return false, fmt.Errorf("failed to list session states: %w", err)
294→	}
295→
296→	for _, state := range states {
297→		if state.SessionID == excludeSessionID {
298→			continue
299→		}
300→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
301→		if otherShadow == shadowBranch && state.StepCount > 0 {
302→			return false, nil
303→		}
304→	}
305→
306→	return true, nil
307→}
