169→func printTranscriptChanges(ctx context.Context, w io.Writer, transcriptPath, currentSession, repoRoot string) int {
170→	fmt.Fprintf(w, "\nParsing transcript: %s\n", transcriptPath)
171→
172→	var modifiedFromTranscript, newFiles, deletedFiles []string
173→
174→	// Parse transcript
175→	parsed, _, parseErr := transcript.ParseFromFileAtLine(transcriptPath, 0)
176→	if parseErr != nil {
177→		fmt.Fprintf(w, "  Error parsing transcript: %v\n", parseErr)
178→	} else {
179→		modifiedFromTranscript = extractModifiedFiles(parsed)
180→		fmt.Fprintf(w, "  Found %d modified files in transcript\n", len(modifiedFromTranscript))
181→	}
182→	// Compute new and deleted files (single git status call)
183→	// Load preState only if we have an active session (needed for new file detection)
184→	var preState *PrePromptState
185→	if currentSession != "" {
186→		var loadErr error
187→		preState, loadErr = LoadPrePromptState(currentSession)
188→		if loadErr != nil {
189→			fmt.Fprintf(w, "  Error loading pre-prompt state: %v\n", loadErr)
190→		}
191→	}
192→	// Always call DetectFileChanges - deleted files don't depend on preState
193→	fileChanges, err := DetectFileChanges(ctx, preState.PreUntrackedFiles())
194→	if err != nil {
195→		fmt.Fprintf(w, "  Error computing file changes: %v\n", err)
196→	}
197→	if fileChanges != nil {
198→		newFiles = fileChanges.New
199→		deletedFiles = fileChanges.Deleted
200→	}
201→
202→	// Filter and normalize paths
203→	modifiedFromTranscript = FilterAndNormalizePaths(modifiedFromTranscript, repoRoot)
204→	newFiles = FilterAndNormalizePaths(newFiles, repoRoot)
205→	deletedFiles = FilterAndNormalizePaths(deletedFiles, repoRoot)
206→
207→	// Print files
208→	printFileList(w, "Modified (from transcript)", "M", modifiedFromTranscript)
209→	printFileList(w, "New files (created during session)", "+", newFiles)
210→	printFileList(w, "Deleted files", "D", deletedFiles)
211→
212→	totalChanges := len(modifiedFromTranscript) + len(newFiles) + len(deletedFiles)
213→	if totalChanges == 0 {
214→		fmt.Fprintln(w, "\nNo changes detected from transcript")
215→	}
216→
217→	return totalChanges
218→}
