284→// getFileChanges returns the current file changes from git status.
285→// Returns (modifiedFiles, untrackedFiles, deletedFiles, stagedFiles, error)
286→func getFileChanges(ctx context.Context) ([]string, []string, []string, []string, error) {
287→	repo, err := openRepository(ctx)
288→	if err != nil {
289→		return nil, nil, nil, nil, err
290→	}
291→
292→	worktree, err := repo.Worktree()
293→	if err != nil {
294→		return nil, nil, nil, nil, fmt.Errorf("getting worktree: %w", err)
295→	}
296→
297→	status, err := worktree.Status()
298→	if err != nil {
299→		return nil, nil, nil, nil, fmt.Errorf("getting status: %w", err)
300→	}
301→
302→	var modifiedFiles, untrackedFiles, deletedFiles, stagedFiles []string
303→
304→	for file, st := range status {
305→		// Skip .entire directory
306→		if paths.IsInfrastructurePath(file) {
307→			continue
308→		}
309→
310→		// Check staging area first
311→		switch st.Staging {
312→		case git.Added, git.Modified:
313→			stagedFiles = append(stagedFiles, file)
314→			continue
315→		case git.Deleted:
316→			deletedFiles = append(deletedFiles, file)
317→			continue
318→		case git.Unmodified, git.Renamed, git.Copied, git.UpdatedButUnmerged, git.Untracked:
319→			// Fall through to check worktree status
320→		}
321→
322→		// Check worktree status
323→		switch st.Worktree {
324→		case git.Modified:
325→			modifiedFiles = append(modifiedFiles, file)
326→		case git.Untracked:
327→			untrackedFiles = append(untrackedFiles, file)
328→		case git.Deleted:
329→			deletedFiles = append(deletedFiles, file)
330→		case git.Unmodified, git.Added, git.Renamed, git.Copied, git.UpdatedButUnmerged:
331→			// No action needed
332→		}
333→	}
334→
335→	// Sort for consistent output
336→	sort.Strings(modifiedFiles)
337→	sort.Strings(untrackedFiles)
338→	sort.Strings(deletedFiles)
339→	sort.Strings(stagedFiles)
340→
341→	return modifiedFiles, untrackedFiles, deletedFiles, stagedFiles, nil
342→}
