344→// findTranscriptForSession attempts to find the transcript file for a session.
345→// Returns the path if found, empty string if not found, or error on failure.
346→func findTranscriptForSession(ctx context.Context, sessionID string) (string, error) {
347→	// Try to get agent type from session state
348→	sessionState, err := strategy.LoadSessionState(ctx, sessionID)
349→	if err != nil {
350→		return "", fmt.Errorf("failed to load session state: %w", err)
351→	}
352→
353→	var ag agent.Agent
354→	if sessionState != nil && sessionState.AgentType != "" {
355→		ag, err = agent.GetByAgentType(sessionState.AgentType)
356→		if err != nil {
357→			return "", fmt.Errorf("failed to get agent for type %q: %w", sessionState.AgentType, err)
358→		}
359→	} else {
360→		return "", fmt.Errorf("failed to get agent from sessionID: %s", sessionID)
361→	}
362→
363→	// Resolve transcript path (checks session state's transcript_path first,
364→	// falls back to agent's GetSessionDir + ResolveSessionFile)
365→	transcriptPath, err := resolveTranscriptPath(sessionID, ag)
366→	if err != nil {
367→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
368→	}
369→
370→	// Check if it exists
371→	if _, err := os.Stat(transcriptPath); err != nil {
372→		if os.IsNotExist(err) {
373→			return "", nil // Not found, but not an error
374→		}
375→		return "", fmt.Errorf("failed to stat transcript: %w", err)
376→	}
377→
378→	return transcriptPath, nil
379→}
