176→// branchCheckpointResult contains the result of searching for a checkpoint on a branch.
177→type branchCheckpointResult struct {
178→	checkpointID      id.CheckpointID
179→	commitHash        string
180→	commitMessage     string
181→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
182→	newerCommitCount  int  // count of branch-only commits without checkpoints
183→}
184→
185→// findBranchCheckpoint finds the most recent commit with an Entire-Checkpoint trailer
186→// among commits that are unique to this branch (not reachable from the default branch).
187→// This handles the case where main has been merged into the feature branch.
188→func findBranchCheckpoint(repo *git.Repository, branchName string) (*branchCheckpointResult, error) {
189→	result := &branchCheckpointResult{}
190→
191→	// Get HEAD commit
192→	head, err := repo.Head()
193→	if err != nil {
194→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
195→	}
196→
197→	headCommit, err := repo.CommitObject(head.Hash())
198→	if err != nil {
199→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
200→	}
201→
202→	// First, check if HEAD itself has a checkpoint (most common case)
203→	if cpID, found := trailers.ParseCheckpoint(headCommit.Message); found {
204→		result.checkpointID = cpID
205→		result.commitHash = head.Hash().String()
206→		result.commitMessage = headCommit.Message
207→		result.newerCommitsExist = false
208→		return result, nil
209→	}
210→
211→	// HEAD doesn't have a checkpoint - find branch-only commits
212→	// Get the default branch name
213→	defaultBranch := getDefaultBranchFromRemote(repo)
214→	if defaultBranch == "" {
215→		// Fallback: try common names
216→		for _, name := range []string{"main", "master"} {
217→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
218→				defaultBranch = name
219→				break
220→			}
221→		}
222→	}
223→
224→	// If we can't find a default branch, or we're on it, just walk all commits
225→	if defaultBranch == "" || defaultBranch == branchName {
226→		return findCheckpointInHistory(headCommit, nil), nil
227→	}
228→
229→	// Get the default branch reference
230→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
231→	if err != nil {
232→		// Default branch doesn't exist locally, fall back to walking all commits
233→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
234→	}
235→
236→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
237→	if err != nil {
238→		// Can't get default commit, fall back to walking all commits
239→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
240→	}
241→
242→	// Find merge base
243→	mergeBase, err := headCommit.MergeBase(defaultCommit)
244→	if err != nil || len(mergeBase) == 0 {
245→		// No common ancestor, fall back to walking all commits
246→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
247→	}
248→
249→	// Walk from HEAD to merge base, looking for checkpoint
250→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
251→}
252→
253→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
254→// If stopAt is provided, stops when reaching that commit (exclusive).
255→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
256→// It distinguishes between merge commits (bringing in other branches) and regular commits
257→// (actual branch work) to avoid false warnings after merging main.
258→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointResult {
259→	result := &branchCheckpointResult{}
260→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
261→	const maxCommits = 100 // Limit search depth
262→	totalChecked := 0
263→
264→	current := start
265→	for current != nil && totalChecked < maxCommits {
266→		// Stop if we've reached the boundary
267→		if stopAt != nil && current.Hash == *stopAt {
268→			break
269→		}
270→
271→		// Check for checkpoint trailer
272→		if cpID, found := trailers.ParseCheckpoint(current.Message); found {
273→			result.checkpointID = cpID
274→			result.commitHash = current.Hash.String()
275→			result.commitMessage = current.Message
276→			// Only warn about branch work commits, not merge commits
277→			result.newerCommitsExist = branchWorkCommits > 0
278→			result.newerCommitCount = branchWorkCommits
279→			return result
280→		}
281→
282→		// Only count regular commits (not merge commits) as "branch work"
283→		if current.NumParents() <= 1 {
284→			branchWorkCommits++
285→		}
286→
287→		totalChecked++
288→
289→		// Move to parent (first parent for merge commits - follows the main line)
290→		if current.NumParents() == 0 {
291→			break
292→		}
293→		parent, err := current.Parent(0)
294→		if err != nil {
295→			// Can't get parent, treat as end of history
296→			break
297→		}
298→		current = parent
299→	}
300→
301→	// No checkpoint found
302→	return result
303→}
