327→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
328→// and automatically fetches it if available.
329→func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
330→	// Try to get remote metadata branch tree
331→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
332→	if err != nil {
333→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
334→		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
335→		return nil //nolint:nilerr // Informational message, not a fatal error
336→	}
337→
338→	// Check if the checkpoint exists on the remote
339→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
340→	if err != nil {
341→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
342→		return nil //nolint:nilerr // Informational message, not a fatal error
343→	}
344→
345→	// Metadata exists on remote but not locally - fetch it automatically
346→	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
347→	if err := FetchMetadataBranch(ctx); err != nil {
348→		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
349→		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
350→		return NewSilentError(errors.New("failed to fetch metadata"))
351→	}
352→
353→	// Now resume the session with the fetched metadata
354→	return resumeSession(ctx, metadata.SessionID, checkpointID, false)
355→}
