357→// resumeSession restores and displays the resume command for a specific session.
358→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
359→// If force is false, prompts for confirmation when local logs have newer timestamps.
360→func resumeSession(ctx context.Context, sessionID string, checkpointID id.CheckpointID, force bool) error {
361→	// Read checkpoint metadata first to get agent type (matching rewind pattern)
362→	repo, err := openRepository(ctx)
363→	if err != nil {
364→		return fmt.Errorf("failed to open repository: %w", err)
365→	}
366→
367→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
368→	if err != nil {
369→		return fmt.Errorf("failed to get metadata branch: %w", err)
370→	}
371→
372→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
373→	if err != nil {
374→		return fmt.Errorf("failed to read checkpoint metadata: %w", err)
375→	}
376→
377→	// Resolve agent from checkpoint metadata (same as rewind)
378→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
379→	if err != nil {
380→		return fmt.Errorf("failed to resolve agent: %w", err)
381→	}
382→
383→	// Initialize logging context with agent
384→	ctx = logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
385→
386→	logging.Debug(ctx, "resume session started",
387→		slog.String("checkpoint_id", checkpointID.String()),
388→		slog.String("session_id", sessionID),
389→	)
390→
391→	// Get repo root for session directory lookup
392→	repoRoot, err := paths.RepoRoot(ctx)
393→	if err != nil {
394→		return fmt.Errorf("failed to get repository root: %w", err)
395→	}
396→
397→	sessionDir, err := ag.GetSessionDir(repoRoot)
398→	if err != nil {
399→		return fmt.Errorf("failed to determine session directory: %w", err)
400→	}
401→
402→	// Create directory if it doesn't exist
403→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
404→		return fmt.Errorf("failed to create session directory: %w", err)
405→	}
406→
407→	// Get strategy and restore sessions using full checkpoint data
408→	strat := GetStrategy()
409→
410→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
411→	if restorer, ok := strat.(strategy.LogsOnlyRestorer); ok {
412→		// Create a logs-only rewind point with Agent populated (same as rewind)
413→		point := strategy.RewindPoint{
414→			IsLogsOnly:   true,
415→			CheckpointID: checkpointID,
416→			Agent:        metadata.Agent,
417→		}
418→
419→		sessions, restoreErr := restorer.RestoreLogsOnly(ctx, point, force)
420→		if restoreErr != nil || len(sessions) == 0 {
421→			// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
422→			return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
423→		}
424→
425→		// Sort sessions by CreatedAt so the most recent is last (for display).
426→		// This fixes ordering when subdirectory index doesn't reflect activity order.
427→		sort.Slice(sessions, func(i, j int) bool {
428→			return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
429→		})
430→
431→		logging.Debug(ctx, "resume session completed",
432→			slog.String("checkpoint_id", checkpointID.String()),
433→			slog.Int("session_count", len(sessions)),
434→		)
435→
436→		// Print per-session resume commands using returned sessions
437→		if len(sessions) > 1 {
438→			fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
439→		} else if len(sessions) == 1 {
440→			fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
441→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
442→		}
443→		for i, sess := range sessions {
444→			sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
445→			if err != nil {
446→				return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
447→			}
448→			cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
449→
450→			if len(sessions) > 1 {
451→				if i == len(sessions)-1 {
452→					if sess.Prompt != "" {
453→						fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
454→					} else {
455→						fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
456→					}
457→				} else {
458→					if sess.Prompt != "" {
459→						fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
460→					} else {
461→						fmt.Fprintf(os.Stderr, "  %s\n", cmd)
462→					}
463→				}
464→			} else {
465→				if sess.Prompt != "" {
466→					fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
467→				} else {
468→					fmt.Fprintf(os.Stderr, "  %s\n", cmd)
469→				}
470→			}
471→		}
472→
473→		return nil
474→	}
475→
476→	// Strategy doesn't support LogsOnlyRestorer, fall back to single session
477→	return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
478→}
