480→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
481→// Always overwrites existing session logs to ensure consistency with checkpoint state.
482→// If force is false, prompts for confirmation when local log has newer timestamps.
483→func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
484→	sessionLogPath, err := resolveTranscriptPath(sessionID, ag)
485→	if err != nil {
486→		return fmt.Errorf("failed to resolve transcript path: %w", err)
487→	}
488→
489→	if checkpointID.IsEmpty() {
490→		logging.Debug(ctx, "resume session: empty checkpoint ID",
491→			slog.String("checkpoint_id", checkpointID.String()),
492→		)
493→		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
494→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
495→		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
496→		return nil
497→	}
498→
499→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
500→	if err != nil {
501→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
502→			logging.Debug(ctx, "resume session completed (no metadata)",
503→				slog.String("checkpoint_id", checkpointID.String()),
504→				slog.String("session_id", sessionID),
505→			)
506→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
507→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
508→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
509→			return nil
510→		}
511→		logging.Error(ctx, "resume session failed",
512→			slog.String("checkpoint_id", checkpointID.String()),
513→			slog.String("session_id", sessionID),
514→			slog.String("error", err.Error()),
515→		)
516→		return fmt.Errorf("failed to get session log: %w", err)
517→	}
518→
519→	// Check if local file has newer timestamps than checkpoint
520→	if !force {
521→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
522→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
523→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
524→
525→		if status == strategy.StatusLocalNewer {
526→			sessions := []strategy.SessionRestoreInfo{{
527→				SessionID:      sessionID,
528→				Status:         status,
529→				LocalTime:      localTime,
530→				CheckpointTime: checkpointTime,
531→			}}
532→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
533→			if promptErr != nil {
534→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
535→			}
536→			if !shouldOverwrite {
537→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
538→				return nil
539→			}
540→		}
541→	}
542→
543→	// Ensure parent directory exists
544→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
545→		return fmt.Errorf("failed to create session directory: %w", err)
546→	}
547→
548→	agentSession := &agent.AgentSession{
549→		SessionID:  sessionID,
550→		AgentName:  ag.Name(),
551→		RepoPath:   repoRoot,
552→		SessionRef: sessionLogPath,
553→		NativeData: logContent,
554→	}
555→
556→	// Write the session using the agent's WriteSession method
557→	if err := ag.WriteSession(agentSession); err != nil {
558→		logging.Error(ctx, "resume session failed during write",
559→			slog.String("checkpoint_id", checkpointID.String()),
560→			slog.String("session_id", sessionID),
561→			slog.String("error", err.Error()),
562→		)
563→		return fmt.Errorf("failed to write session: %w", err)
564→	}
565→
566→	logging.Debug(ctx, "resume session completed",
567→		slog.String("checkpoint_id", checkpointID.String()),
568→		slog.String("session_id", sessionID),
569→	)
570→
571→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
572→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
573→	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
574→	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
575→
576→	return nil
577→}
