func TestFormatBranchCheckpoints_SessionFilter(t *testing.T) {
	now := time.Now()
	points := []strategy.RewindPoint{
		{
			ID:            "abc123def456",
			Message:       "Checkpoint from session 1",
			Date:          now,
			CheckpointID:  "chk111111111",
